  webhook: { type: "all" },
});

console.log(run.id, run.status);
```

Handle the webhook event:

```typescript
import { ElevenLabsClient } from "@elevenlabs/elevenlabs-js";

const client = new ElevenLabsClient({
  apiKey: process.env.ELEVENLABS_API_KEY,
});

/**
 * Call from your webhook endpoint with the raw request body and its
 * `elevenlabs-signature` header. Throws on a bad signature.
 */
export async function handleWebhook(rawBody: string, signature: string) {
  const secret = process.env.WEBHOOK_SECRET;
  if (!secret) throw new Error("Set WEBHOOK_SECRET");

  const event = await client.webhooks.constructEvent(rawBody, signature, secret);
  if (event.type !== "flows_template_run") return;

  const run = event.data;
  const packshot = run.outputs["packshot"];
  if (packshot.status === "completed") {
    console.log("packshot", packshot.content_url);
  } else {
    console.error("packshot", "failed:", packshot.failure_reason);
  }
}
```

